syntax:
Type alias using 'typedef':
  typedef existing_type new_type_name;

Type alias using 'using' (preferred in modern C++):
  using new_type_name = existing_type;

Note: 'using' can also be used for alias templates, which 'typedef' cannot do.

code_example:
#include <string>
#include <locale>

using char_type = char;  // Modern type alias using 'using'
using string_type = std::basic_string<char_type>;  // Alias for a string type

class MoneyPunct : public std::locale::facet {
public:
    explicit MoneyPunct(size_t refs = 0) : std::locale::facet(refs) {}
    virtual char_type decimal_point() const = 0;
    virtual char_type thousands_sep() const = 0;
    virtual std::string grouping() const = 0;
    virtual string_type curr_symbol() const = 0;
    virtual string_type positive_sign() const = 0;
    virtual string_type negative_sign() const = 0;
    virtual int frac_digits() const = 0;
    virtual std::locale::pattern pos_format() const = 0;
    virtual std::locale::pattern neg_format() const = 0;
    static const std::locale::id id;
    static const bool intl = true;
};
